    'additional_tax_classes' => 'கூடுதல் வரி வகுப்புகள்',
    'additional_tax_classes_hint' => 'தரத்திற்கு அப்பாற்பட்ட வரி வகுப்புகளைச் சேர்க்கவும் (எ.கா. குறைக்கப்பட்ட விகிதம், டிஜிட்டல் பொருட்கள்). பெயரைத் தட்டச்சு செய்து Enter ஐ அழுத்தவும். ஒவ்வொன்றும் வரி விகிதங்களின் கீழ் ஒரு தாவலாக மாறும் மற்றும் தயாரிப்புகளுக்கு ஒதுக்கப்படலாம்.',
    'tt_tax_name' => 'இந்த வரிக்கான காட்சிப் பெயர் (எ.கா. VAT, GST, விற்பனை வரி). இது விலைப்பட்டியல்களில் தோன்றும்.',
    'tt_rate' => 'வரி விகிதம் சதவீதமாக. தசமங்கள் அனுமதிக்கப்படுகின்றன (எ.கா. 18 அல்லது 7.5).',
    'tt_tax_class' => 'இந்த விகிதம் சேர்ந்த வரி வர்க்கம். ஒரு தயாரிப்புக்கு ஒதுக்கப்பட்ட வகுப்பில் உள்ள விகிதங்களால் வரி விதிக்கப்படுகிறது.',
    'tt_country' => 'இந்த விகிதம் பொருந்தும் நாடு. எல்லா இடங்களிலும் பயன்படுத்த "அனைத்து நாடுகளும்" என்பதைத் தேர்ந்தெடுக்கவும்.',
    'tt_state' => 'மாநிலம்/மாகாணம் இந்த விகிதம் பொருந்தும். முழு நாட்டையும் உள்ளடக்குவதற்கு "அனைத்து மாநிலங்கள்" என்பதைத் தேர்ந்தெடுக்கவும்.',
    'tt_priority' => 'இந்த வரி விகிதத்திற்கான முன்னுரிமையைத் தேர்வு செய்யவும். ஒரு முன்னுரிமைக்கு ஒரு பொருத்த விகிதம் மட்டுமே பயன்படுத்தப்படுகிறது. ஒரே ஆர்டரில் ஒன்றுக்கும் மேற்பட்ட வரிகளை வசூலிக்க, ஒவ்வொரு விகிதத்திற்கும் வெவ்வேறு முன்னுரிமை கொடுங்கள்.',
    'tt_compound' => 'ஆம் எனில், இந்த வரியானது அடிப்படை விலையில் மட்டுமல்ல, ஏற்கனவே பயன்படுத்தப்பட்ட பிற வரிகளின் மேல் (வரி மீதான வரி) கணக்கிடப்படும்.',
    'tt_status' => 'வரி கணக்கீட்டின் போது செயலற்ற விகிதங்கள் தவிர்க்கப்படுகின்றன.',
    'tt_postcode' => 'விருப்பமானது. குறிப்பிட்ட அஞ்சல் குறியீடுகளுக்கு இந்த விகிதத்தைக் கட்டுப்படுத்தவும். வைல்டு கார்டுகள் (12*) மற்றும் வரம்புகளை (12000...12999) ஆதரிக்கிறது; காற்புள்ளிகளுடன் பல பிரிக்கவும்.',
    'tt_city' => 'விருப்பமானது. காற்புள்ளிகளால் பிரிக்கப்பட்ட குறிப்பிட்ட நகரங்களுக்கு இந்த விகிதத்தைக் கட்டுப்படுத்தவும். அனைத்து நகரங்களுக்கும் விண்ணப்பிக்க காலியாக விடவும்.',
    'tt_tax_enable' => 'முழு கடைக்கும் வரி கணக்கீட்டை இயக்கவும் அல்லது முடக்கவும்.',
    'tt_inclusive' => 'உள்ளடக்கியது: உங்கள் தயாரிப்பு விலைகளில் ஏற்கனவே வரி அடங்கும். பிரத்தியேகமானது: செக் அவுட்டின் மேல் வரி சேர்க்கப்படும்.',
    'tt_rounding' => '2 தசமங்களை வைப்பதற்குப் பதிலாக இறுதி வரி/மொத்தத்தை முழு எண்ணாகச் சுற்றவும்.',
