    'zoho_no_fields' => 'Zoho புலங்கள் எதுவும் இல்லை. Zoho இலிருந்து புலங்களைப் பெற "புலங்களை ஒத்திசை" என்பதைக் கிளிக் செய்யவும்.',
    'zoho_redirect_uri_help' => 'இந்த சரியான URL ஐ உங்கள் Zoho API கன்சோலில் அங்கீகரிக்கப்பட்ட வழிமாற்று URI ஆகச் சேர்க்கவும்.',
    'zoho_mapping_info' => 'ஃபேவியோ இன்வாய்சிங் மற்றும் ஜோஹோ இடையே உங்கள் தொடர்புகளை ஒத்திசைக்க, நீங்கள் வரைபடமாக்க விரும்பும் புலங்களைத் தேர்வு செய்யவும். இடதுபுறத்தில் உள்ள Zoho புலத்தையும், வலதுபுறத்தில் தொடர்புடைய Faveo புலத்தையும் தேர்ந்தெடுக்கவும்.',
    'zoho_mapping_owner_blocked' => ':field: இந்த புலம் Zoho ஆல் நிர்வகிக்கப்படுகிறது மற்றும் Zoho பயனர் தேவை. நீங்கள் அதற்கு ஒரு உள்ளூர் புலத்தை வரைபடமாக்க தேவையில்லை; Zoho அதை தானாகவே ஒதுக்கும்.',
    'zoho_mapping_lookup_blocked' => ':field: இந்த புலம் Zoho இல் ஏற்கனவே உள்ள பதிவுடன் இணைக்கப்பட வேண்டும். ஒரு உள்ளூர் புலத்தை இங்கே பயன்படுத்த முடியாது, ஏனெனில் அது ஏற்கனவே உள்ளதை இணைப்பதற்குப் பதிலாக நகல் பதிவை உருவாக்கலாம்.',
    'zoho_mapping_image_blocked' => ':field: இந்தப் புலத்திற்கு Zoho இல் பதிவேற்றப்பட்ட படம் தேவை. உள்ளூர் புலம் அதை வழங்க முடியாது, எனவே அதை இங்கே வரைபடமாக்க முடியாது.',
    'zoho_mapping_datetime_blocked' => ':field: இந்த புலம் Zoho ஆல் நிர்வகிக்கப்படுகிறது மற்றும் தானாகவே புதுப்பிக்கப்படும். உள்ளூர் புலத்தை வரைபடமாக்குவது எந்த விளைவையும் ஏற்படுத்தாது.',
    'zoho_mapping_picklist_has_options' => ':field:Zoho இந்தத் துறைக்கான விருப்பங்களின் முன் வரையறுக்கப்பட்ட பட்டியலை வழங்குகிறது. உள்ளூர் புலத்தை மேப்பிங் செய்வதற்குப் பதிலாக கிடைக்கக்கூடிய Zoho விருப்பங்களில் ஒன்றைத் தேர்ந்தெடுக்கவும்.',
    'zoho_mapping_type_mismatch' => ':field: இந்த புலம் Zoho இல் :zoho_type ஐ எதிர்பார்க்கிறது, ஆனால் \':local_field\' :local_typeஐ மட்டுமே கொண்டுள்ளது. சரியான வகையின் உள்ளூர் புலத்தைத் தேர்வு செய்யவும், இல்லையெனில் இந்த மேப்பிங்கைப் பயன்படுத்தும் போது Zoho முழுப் பதிவையும் நிராகரிக்கும்.',
