    'github_invalid' => 'அங்கீகாரம் தோல்வியடைந்தது. உங்கள் GitHub பயனர்பெயர் மற்றும் தனிப்பட்ட அணுகல் டோக்கனை சரிபார்க்கவும்.',
    'github_valid' => 'GitHub அமைப்புகள் வெற்றிகரமாக சேமிக்கப்பட்டது.',
    'pat' => 'தனிப்பட்ட அணுகல் டோக்கன்',
    'invalid_recaptcha_key' => 'Google reCAPTCHA தளம் விசை தவறானது',
    'status_change' => 'நிலை மாற்றப்பட்டது',
    'google_description' => 'Google reCAPTCHA ஒருங்கிணைப்பு அனைத்து அங்கீகாரம் செய்யப்படாத பக்கங்களில் reCAPTCHA அம்சத்தை சேர்க்கிறது, உங்கள் படிவங்களை பாட்டுகள் மற்றும் தானியங்கி சமர்ப்பிப்புகளிலிருந்து பாதுகாக்கிறது, உண்மையான பயனர்கள் மட்டுமே தகவலை சமர்ப்பிக்க முடியும் என்பதில் உறுதி செய்கிறது.',
    'license_description' => 'Faveo License Manager ஒருங்கிணைப்பு Faveo Invoicing இல் மென்பொருள் உரிமங்கள் மற்றும் புதுப்பிப்புகளை நிர்வகிக்கும் திறனைக் கூட்டுகிறது, தளத்தின் மூலம் நேரடியாக உரிமங்கள் மற்றும் புதுப்பிப்புகளை எளிதில் கண்காணிக்க மற்றும் செயல்படுத்த உதவுகிறது.',
    'msg91_description' => 'MSG91.com சேவை பதிவு போது தொடர்புடைய மொபைல் எண்ணை உறுதிப்படுத்த OTPகளை (ஒரு முறை கடவுச்சொல்) அனுப்ப பயன்படுத்தப்படுகிறது, இது பாதுகாப்பான மற்றும் நம்பகமான தொடர்பு உறுதிப்படுத்தல் முறையாக செயல்படுகிறது.',
    'mailchimp_description' => 'Mailchimp பிளகின் Faveo Invoicing இலிருந்து அனைத்து தொடர்பு தரவையும் பதிவு மற்றும் சுயவிவரத் திருத்தங்களின் போது Mailchimp இல் தானாக அனுப்புகிறது. கூடுதலாக, வாங்கும் தரவுகளும் Mailchimp உடன் பொருத்தக்கூடியவை. தனித்துவமான பொருத்தல் பக்கம் எந்த தரவுகள் இரு தளங்களுக்கும் ஒத்திசைக்கப்பட வேண்டும் என்பதை பயனர்களுக்கு தனிப்பயனாக்க அனுமதிக்கிறது.',
    'terms_description' => '\'பதிவுப் பக்கத்தில் விதிமுறைகளை காட்டு\' என்ற விருப்பம் செயல்படுத்தப்பட்டால், பதிவு பக்கத்தில் ஒரு செக்பாக்ஸ் தோன்றும், பயனர்கள் பதிவு முடிக்க முன் விதிமுறைகள் மற்றும் நிபந்தனைகளுக்கு ஒப்புதல் அளிக்க வேண்டும்.',
    'pipedrive_description' => 'Pipedrive CRM பிளகின் Faveo Invoicing இலிருந்து அனைத்து தொடர்பு தரவையும் பதிவு மற்றும் சுயவிவர திருத்தங்களின் போது Pipedrive CRM இல் தானாக அனுப்புகிறது. தனித்துவமான பொருத்தல் பக்கம் எந்த தரவு புலங்கள் ஒத்திசைக்கப்பட வேண்டும் என்பதனை தனிப்பயனாக்க பயனர்களுக்கு அனுமதிக்கிறது.',
    'github_description' => 'GitHub ஒருங்கிணைப்பு GitHub ரெப்போசிடரி இலிருந்து நேரடியாக தயாரிப்புகளைப் பெற மற்றும் பதிவிறக்கம் செய்யும் திறனை அதிகரிக்கிறது, உங்கள் GitHub திட்டங்களில் இருந்து கோப்புகளை அணுகவும் நிர்வகிக்கவும் செயல்முறையை எளிமைப்படுத்துகிறது.',
    'license_heading' => 'தானாக Faveo உரிமையாளர்ப் பதிவும் புதுப்பிப்பு மேலாளரும்',
