    'terms_url_s' => 'தயவுசெய்து செல்லுபடியாகும் விதிமுறைகள் URL ஐ உள்ளிடவும்.',
    'pipedrive_key_s' => 'தயவுசெய்து செல்லுபடியாகும் Pipedrive விசையை உள்ளிடவும்.',
    'git_username_s' => 'தயவுசெய்து செல்லுபடியாகும் Git பயனர்பெயரை உள்ளிடவும்.',
    'git_password_s' => 'தயவுசெய்து செல்லுபடியாகும் Git தனிப்பட்ட அணுகல் டோக்கனை உள்ளிடவும்.',
    'git_client_s' => 'தயவுசெய்து செல்லுபடியாகும் Git கிளையண்ட் ஐடியை உள்ளிடவும்.',
    'git_secret_s' => 'தயவுசெய்து செல்லுபடியாகும் Git கிளையண்ட் ரகசியத்தை உள்ளிடவும்.',
    'list_id_error' => 'தயவுசெய்து செல்லுபடியாகும் பட்டியல் ஐடியை தேர்ந்தெடுக்கவும்.',
    'subscribe_status_error' => 'தயவுசெய்து செல்லுபடியாகும் சந்தா நிலையை தேர்ந்தெடுக்கவும்.',
    'recaptcha_type_error' => 'தயவுசெய்து reCAPTCHA வகையை தேர்ந்தெடுக்கவும்.',
    'third_party_key_error' => 'தயவுசெய்து செல்லுபடியாகும் Msg91 பயன்பாட்டு விசையை தேர்ந்தெடுக்கவும்.',
