    'sync_fields_hint' => 'மேப்பிங் செய்வதற்கு முன் உங்கள் Mailchimp ஒன்றிணைப்பு குறிச்சொற்களை ஏற்றுவதற்கு "புலங்களை ஒத்திசை" என்பதைக் கிளிக் செய்யவும்.',
    'pending' => 'நிலுவையில்',
    'no_results' => 'முடிவுகள் இல்லை',
    'mailchimp_field_mapping_info' => 'உங்கள் Faveo பயனர் புலங்களை உங்கள் Mailchimp ஒன்றிணைப்பு குறிச்சொற்களுக்கு வரைபடமாக்குங்கள். பயனர் சேர்க்கப்படும்போது அல்லது புதுப்பிக்கப்படும்போது வரைபடப் புலங்கள் மட்டுமே ஒத்திசைக்கப்படும்.',
    'faveo_fields' => 'Faveo Invoicing புலங்கள்',
    'mailchimp_merge_tag' => 'Mailchimp மெர்ஜ் டேக்',
    'select_field' => 'புலத்தைத் தேர்ந்தெடுக்கவும்',
    'group_fields_mapping_info' => 'ஒவ்வொரு தயாரிப்பையும் Mailchimp ஆர்வமுள்ள குழுவிற்கு வரைபடமாக்குங்கள். வாங்கிய பிறகு, வாடிக்கையாளர் வரைபட வட்டி குழுவின் கீழ் குறியிடப்படுவார்.',
    'map_is_paid_info' => 'ஆம்/உண்மை மற்றும் இல்லை/தவறு என்ற இரண்டு விருப்பங்களைக் கொண்ட Mailchimp வட்டி வகையைத் தேர்ந்தெடுக்கவும். ஒவ்வொரு வாங்குதலுக்கும் பிறகு, வாடிக்கையாளர்கள் அதற்கேற்ப குறியிடப்படுவார்கள்.',
    'connection' => 'இணைப்பு',
