    'mailchimp_select_list_first' => 'தயவுசெய்து இணைத்து, முதலில் அஞ்சல் பட்டியலைத் தேர்ந்தெடுக்கவும்.',
    'group_fields_mapping' => 'குழு புலங்கள் மேப்பிங்',
    'group_fields_mapping_hint' => 'Mailchimp இல் உருவாக்கப்பட்ட குழு புலங்களுடன் உங்கள் தயாரிப்புகள் அனைத்தையும் வரைபடமாக்குங்கள். ஒரு பொருளை வாங்கிய பிறகு, அந்த தயாரிப்புடன் மேப் செய்யப்பட்ட Mailchimp குழு புலம் Mailchimp கணக்கு குழுவின் பிரிவில் காண்பிக்கப்படும்.',
    'sync_groups' => 'குழுக்களை ஒத்திசைக்கவும்',
    'sync_groups_hint' => 'மேப்பிங் செய்வதற்கு முன் உங்கள் Mailchimp ஆர்வக் குழுக்களை ஏற்ற, "குழுக்களை ஒத்திசை" என்பதைக் கிளிக் செய்யவும்.',
    'no_interest_groups_found' => 'இந்தப் பட்டியலுக்கு ஆர்வமுள்ள குழுக்கள் எதுவும் இல்லை. முதலில் உங்கள் Mailchimp கணக்கில் வட்டி வகைகளை உருவாக்கவும்.',
    'interest_group' => 'வட்டி குழு',
    'map_is_paid_group' => 'வரைபடம் செலுத்தப்பட்ட குழு',
    'map_is_paid_hint' => 'இந்த அமைப்பு தயாரிப்பு கட்டணம் விதிக்கப்பட்டதா அல்லது இலவசமா என்பதை வரையறுக்கிறது. Mailchimp இல் கீழ்தோன்றும் மதிப்புகளுடன் ஒரு குழுவை உருவாக்கவும், அது ஆம்/இல்லை அல்லது உண்மை/தவறு என இருக்க வேண்டும். சேமிக்கப்பட்டதும், ஒவ்வொரு தயாரிப்பு வாங்கிய பிறகும் அதன் நிலை உங்கள் Mailchimp கணக்கு குழுவின் பிரிவில் பிரதிபலிக்கும்.',
    'pipedrive_user_verification_tooltip' => 'பயனர் சரிபார்ப்பை முடித்த பிறகு மட்டுமே PipeDrive-இல் சேர அனுமதிக்க இந்த விருப்பத்தை இயக்கவும்.',
    'user_verification' => 'PipeDrive இல் பயனரை சேர்க்க சரிபார்ப்பு தேவை',
    'pipedrive_config_info' => 'Faveo Invoicing மற்றும் PipeDrive இடையே உங்கள் தொடர்புகள், நிறுவனங்கள் மற்றும் ஒப்பந்தங்களை ஒத்திசைக்க விருப்பமான புலங்களை தேர்வுசெய்க. சில PipeDrive புலங்கள் இயல்புநிலை விருப்பத்தேர்வுகளைக் கொண்டுள்ளன, அவை பொருத்தத்தின் போது காட்டப்படும். மற்ற அனைத்து புலங்களுக்கும், பொருத்தத்திற்கான கிடைக்கும் Faveo புலங்கள் காட்டப்படும்.',
    'click_pipedrive_sync' => 'ஒத்திசைக்க இங்கே கிளிக் செய்யவும்',
    'person_fields' => 'பயனர் புலங்கள்',
    'deal_fields' => 'ஒப்பந்த புலங்கள்',
    'organization_fields' => 'நிறுவன புலங்கள்',
    'pipedrive_mapping' => 'PipeDrive பொருத்தம்',
    'faveo_invoicing_attributes' => 'Faveo Invoicing பண்புகள்',
    'pipedrive_attributes' => 'PipeDrive பண்புகள்',
    'system_attributes_available' => 'கணினியில் கிடைக்கும் பண்புகள்',
    'pipedrive_attribute_available' => 'PipeDrive பயன்பாட்டின் பண்புகள்',
    'pipedrive_verification_updated' => 'PipeDrive சரிபார்ப்பு நிலை வெற்றிகரமாக புதுப்பிக்கப்பட்டது',
    'sync_pipedrive_fields' => 'இது PipeDrive-இல் உருவாக்கப்பட்ட புதிய புலங்களை ஒத்திசைக்கும் மற்றும் இனி தேவையில்லாத பழைய புலங்களை அகற்றும்.',
    'deal_title_required' => 'PipeDrive இல் ஒப்பந்தங்களை புதுப்பிக்க, Pipedrive தலைப்பு புலம் தேவை. தலைப்பு புலத்தை பொருத்தியது உறுதி செய்யவும்.',
    'empty_group' => 'தற்போது இந்தக் குழுவில் உருப்படிகள் எதுவும் இல்லை, மற்ற குழுக்களைப் பார்க்கவும்.',
    'order_error_modification' => 'வரிசையைப் பார்க்க முடியாது. தவறான தரவு மாற்றம்.',
    'v2_tooltip' => 'செக்பாக்ஸ் மூலம் கோரிக்கைகளை சரிபார்க்கவும்.',
    'v3_tooltip' => 'மதிப்பெண்ணுடன் கோரிக்கைகளை சரிபார்க்கவும்.',
    'user-suspend-successfully' => 'பயனர் வெற்றிகரமாக இடைநீக்கம் செய்யப்பட்டார்.',
    'trial_status_updated' => 'இலவச முயற்சி நிலை வெற்றிகரமாக புதுப்பிக்கப்பட்டது',
    'trial_status_error' => 'இலவச முயற்சி நிலையை புதுப்பிக்கும் போது பிழை ஏற்பட்டது',
    'free_trial_status_tooltip' => 'இலவச முயற்சி பாப்அப் என்பதில் எந்த தயாரிப்பு காண்பிக்க வேண்டும் என்பதை கட்டுப்படுத்த இந்த சுவிட்சைப் பயன்படுத்துங்கள்.',
