    'mobileApisecret' => 'மொபைல் API ரகசியம்',
    'email_validation_success' => 'மின்னஞ்சல் சரிபார்ப்பு சாவி மற்றும் முறை வெற்றிகரமாக சேமிக்கப்பட்டது.',
    'mobile_validation_success' => 'மொபைல் API சாவி, ரகசியம் மற்றும் முறை வெற்றிகரமாக சேமிக்கப்பட்டது.',
    'mobile_validation_success_abstract' => 'மொபைல் சரிபார்ப்பு API சாவி வெற்றிகரமாக சேமிக்கப்பட்டது.',
    'mobile_validation_status' => 'மொபைல் சரிபார்ப்பு நிலை வெற்றிகரமாக சேமிக்கப்பட்டது.',
    'emailApikey_error' => 'தயவுசெய்து சரியான Reoon API சாவியை உள்ளிடவும்.',
    'mobileApikey_error' => 'தயவுசெய்து சரியான சான்றுகளை உள்ளிடவும்.',
    'email_provided_wrong' => 'பாதுகாப்பு காரணங்களால், நீங்கள் வழங்கிய மின்னஞ்சல் முகவரியை ஏற்க முடியவில்லை. தயவுசெய்து வேறு, செல்லுபடியாகும் வணிக மின்னஞ்சலுடன் பதிவு செய்ய முயற்சிக்கவும்.',
    'emailMode_error' => 'தயவுசெய்து மின்னஞ்சல் சரிபார்ப்பு முறையைத் தேர்வு செய்யவும்.',
    'mobileMode_error' => 'தயவுசெய்து மொபைல் சரிபார்ப்பு முறையைத் தேர்வு செய்யவும்.',
    'mobileApisecret_error' => 'தயவுசெய்து சரியான மொபைல் API ரகசியத்தை உள்ளிடவும்.',
    'mobile_provided_wrong' => 'பாதுகாப்பு காரணங்களால், நீங்கள் வழங்கிய மொபைல் எண்ணை ஏற்க முடியவில்லை. தயவுசெய்து வேறு, செல்லுபடியாகும் மொபைல் எண்ணுடன் பதிவு செய்ய முயற்சிக்கவும்.',
    'email_settings_heading' => 'மின்னஞ்சல்-சரிபார்ப்பு-வழங்குநர்கள்',
    'mobile_settings_heading' => 'மொபைல்-சரிபார்ப்பு-வழங்குநர்கள்',
    'mobile_unique' => 'நீங்கள் உள்ளிட்ட மொபைல் எண் ஏற்கனவே பதிவு செய்யப்பட்டுள்ளது. தயவுசெய்து வேறு மொபைல் எண்ணை வழங்கவும்.',
    'email_validation_description' => 'Reoon மின்னஞ்சல் சரிபார்ப்பு ஒருங்கிணைப்பு நேரடி சரிபார்ப்பை வழங்குகிறது, தவறான, தற்காலிக அல்லது ஆபத்தான முகவரிகளை அடையாளம் காண உதவுகிறது. இது மின்னஞ்சல் பட்டியல்களை சுத்தமாக வைத்திருக்க, தவிர்ப்புகளை குறைக்க, மற்றும் மின்னஞ்சல் அனுப்பும் திறனை மேம்படுத்த உதவுகிறது.',
    'mobile_validation_description' => 'மொபைல் சரிபார்ப்பு ஒருங்கிணைப்பு Abstract மற்றும் Vonage API களைப் பயன்படுத்தி எண்ணின் வடிவம், செல்லுபடித்தன்மை, சர்வீஸ் வழங்குநர் விவரங்கள் மற்றும் அணுகக்கூடியதா என்பதை சரிபார்த்து, சரியான மற்றும் அனுப்பக்கூடிய எண்ணுகள் மட்டுமே ஏற்கப்படும் என்பதைக் உறுதி செய்கிறது.',
    'mobileApi_provider' => 'தயவுசெய்து ஒரு மொபைல் சரிபார்ப்பு வழங்குநரைத் தேர்ந்தெடுக்கவும்.',
    'tick-to-hide-from-invoice' => 'நிர்வாகப் பகுதியில் உள்ள தயாரிப்பு கீழ்தோன்றும் பட்டியல்களில் இருந்து மறைக்க குறியை வைக்கவும் (ஏற்கனவே இணைக்கப்பட்ட சேவைகளுக்கு இது பொருந்தாது)',
    'choose_password' => 'உங்கள் கடவுச்சொல்லை மீட்டமைக்க இங்கு கிளிக் செய்யவும்: ',
