    'debugging_settings_saved_message' => 'உங்கள் பிழை மற்றும் பிழைத்திருத்த அமைப்புகள் வெற்றிகரமாகச் சேமிக்கப்பட்டன',
    'plugin_compatible_tooltip' => 'இந்த சொருகி இந்த தயாரிப்புடன் வேலை செய்கிறது. இது தொகுக்கப்பட்டதாகக் குறிக்கப்பட்டிருந்தால் அது தயாரிப்புடன் சேர்க்கப்படலாம் அல்லது வாடிக்கையாளர் அதை ஒரு துணை நிரலாக தனித்தனியாக வாங்கலாம். ஒரு செருகுநிரலை இணக்கமானது எனக் குறிப்பது, அது ஆதரிக்கப்பட்டு, இந்தத் தயாரிப்புடன் இணைந்து செயல்படுவதாக அங்கீகரிக்கப்பட்டுள்ளது.',
    'plugin_bundled_tooltip' => 'இந்த சொருகி தானாகவே தயாரிப்புடன் சேர்க்கப்பட்டுள்ளது. ஒரு வாடிக்கையாளர் இந்த தயாரிப்பை வாங்கும் போது, ​​அவர்களும் இந்த செருகுநிரலைப் பெறுவார்கள் - கூடுதல் படிகள் அல்லது கூடுதல் கட்டணம் தேவையில்லை. இது தயாரிப்புடன் வருவதால், இது தானாகவே இணக்கமானது எனக் குறிக்கப்படும், மேலும் அதைத் தேர்வுசெய்ய முடியாது.',
