    'deployment_settings' => 'வரிசைப்படுத்தல் அமைப்புகள்',
    'deployment_enabled_tooltip' => 'கிளையன்ட் ஆர்டர் பக்கங்களில் வரிசைப்படுத்து தாவல் தோன்றுவதைக் கட்டுப்படுத்துகிறது. இயக்கப்பட்டால், வாடிக்கையாளர்கள் SSH வழியாக தங்கள் சொந்த சேவையகத்துடன் இணைக்கலாம் மற்றும் பில்லிங் போர்ட்டலில் இருந்து நேரடியாக ஃபேவியோ ஹெல்ப்டெஸ்க்கை வரிசைப்படுத்தலாம். அனைத்து கிளையண்டுகளிடமிருந்தும் வரிசைப்படுத்து தாவலை மறைக்க இதை முடக்கவும்.',
    'install_script_url_tooltip' => 'புதிய சர்வரில் முழு ஃபேவியோ ஹெல்ப்டெஸ்க் நிறுவலைச் செய்யும் ஷெல் ஸ்கிரிப்ட்டுக்கான URL - இது PHP, ஒரு வெப் சர்வர் (Apache அல்லது Nginx), MariaDB, Redis மற்றும் Supervisor ஆகியவற்றை தானாகவே நிறுவுகிறது. கிளையன்ட் புதிய சேவையக வரிசைப்படுத்தல் பயன்முறையைத் தேர்ந்தெடுக்கும்போது இந்த ஸ்கிரிப்ட் செயல்படுத்தப்படுகிறது. நீங்கள் புதிய சேவையக நிறுவல்களை ஆதரிக்க விரும்பவில்லை என்றால் மட்டும் காலியாக விடவும்.',
    'manual_install_guide_url_tooltip' => 'வழிகாட்டப்பட்ட SSH வழிகாட்டிக்கு மாற்றாக வாடிக்கையாளர்களுக்கு காட்டப்படும் படிப்படியான நிறுவல் ஆவணங்களுக்கான இணைப்பு. சேவையகத்தை அமைக்க விரும்பும் வாடிக்கையாளர்கள் அதற்கு பதிலாக இந்த வழிகாட்டியைப் பின்பற்றலாம். பொதுவாக உங்கள் தயாரிப்பு ஆவணத்திற்கான URL (எ.கா. https://docs.example.com/install).',
