    'no_description_available' => 'விளக்கம் கிடைக்கவில்லை.',
    'gateway_desc_paypal' => 'PayPal ஐப் பயன்படுத்தி உலகளவில் பணம் செலுத்துவதை ஏற்கவும் — 200+ நாடுகள் மற்றும் பல நாணயங்களை ஆதரிக்கும் மிகவும் நம்பகமான ஆன்லைன் கட்டண தளங்களில் ஒன்று.',
    'gateway_desc_stripe' => 'ஸ்ட்ரைப்பின் சக்திவாய்ந்த டெவலப்பர்-நட்பு கட்டண உள்கட்டமைப்புடன் உலகளவில் கார்டுகள், பணப்பைகள் மற்றும் உள்ளூர் கட்டண முறைகளை செயலாக்கவும்.',
    'gateway_desc_razorpay' => 'தடையற்ற செக்அவுட் அனுபவத்துடன் UPI, கார்டுகள், நெட் பேங்கிங், வாலட்கள் மற்றும் EMI ஆகியவற்றை ஆதரிக்கும் இந்தியாவின் முன்னணி கட்டண நுழைவாயில்.',
    'gateway_desc_amazon' => 'வேகமான, நம்பகமான மற்றும் பரிச்சயமான செக் அவுட் அனுபவத்திற்காக வாடிக்கையாளர்கள் தங்கள் Amazon கணக்குச் சான்றுகளைப் பயன்படுத்தி பணம் செலுத்த அனுமதிக்கவும்.',
    'gateway_desc_google' => 'Google Pay மூலம் வேகமான மற்றும் பாதுகாப்பான செக் அவுட்டை இயக்கு — Android, Chrome மற்றும் இணையம் முழுவதும் வேலை செய்யும்.',
    'gateway_desc_apple' => 'ஆப்பிள் பே வழியாக ஃபேஸ் ஐடி, டச் ஐடி அல்லது கடவுக்குறியீட்டைப் பயன்படுத்தி விரைவாகவும் பாதுகாப்பாகவும் பணம் செலுத்த ஆப்பிள் சாதனப் பயனர்களை அனுமதிக்கவும்.',
    'gateway_desc_mollie' => 'ஒரு நெகிழ்வான ஐரோப்பிய கட்டண நுழைவாயில் வழங்கும் அட்டைகள், iDEAL, Bancontact, SEPA மற்றும் பல உள்ளூர் முறைகள்.',
    'gateway_desc_paytm' => 'UPI, கார்டுகள், நெட் பேங்கிங் மற்றும் Paytm வாலட்டை ஆதரிக்கும் இந்தியாவின் பிரபலமான டிஜிட்டல் வாலட் மற்றும் பேமெண்ட் கேட்வே.',
    'gateway_desc_cashfree' => 'பேஅவுட்கள், சந்தாக்கள் மற்றும் உடனடி தீர்வுகளுக்கான ஆதரவுடன் இந்திய வணிகங்களுக்கான வேகமான மற்றும் நம்பகமான கட்டண நுழைவாயில்.',
    'gateway_desc_instamojo' => 'இந்திய SMB களுக்கான எளிய கட்டண நுழைவாயில் - இணைப்புகள், UPI, கார்டுகள் மற்றும் பணப்பைகள் மூலம் பணம் செலுத்துவதை பூஜ்ஜிய அமைவு கட்டணத்துடன் ஏற்கவும்.',
    'gateway_desc_flutterwave' => 'பான்-ஆப்பிரிக்க பேமெண்ட் பிளாட்ஃபார்ம் வணிகங்கள் ஆப்பிரிக்கா மற்றும் அதற்கு அப்பால் பணம் செலுத்துவதை ஏற்கவும் அனுப்பவும் உதவுகிறது.',
    'gateway_desc_paystack' => 'கார்டுகள், வங்கி பரிமாற்றங்கள், USSD மற்றும் மொபைல் பணத்திற்கான ஆதரவுடன் ஆப்பிரிக்காவின் முன்னணி கட்டண நுழைவாயில்.',
    'gateway_desc_square' => 'தனிநபர் மற்றும் ஆன்லைன் கட்டணங்கள், சரக்கு மேலாண்மை மற்றும் வணிக பகுப்பாய்வுகளுடன் ஒருங்கிணைந்த வர்த்தக தீர்வு.',
    'gateway_desc_braintree' => 'அட்டைகள், PayPal, Venmo மற்றும் உள்ளூர் முறைகளுக்கான ஆதரவுடன் நெகிழ்வான கட்டண ஒருங்கிணைப்புகளை வழங்கும் PayPal சேவை.',
    'gateway_desc_authorize' => 'பாதுகாப்பான அட்டை செயலாக்கம் மற்றும் மோசடி கண்டறிதலை வழங்கும் அமெரிக்காவில் மிகவும் நிறுவப்பட்ட கட்டண நுழைவாயில்களில் ஒன்று.',
    'gateway_desc_ccavenue' => 'கார்டுகள், நெட் பேங்கிங், UPI மற்றும் பணப்பைகள் உட்பட 200+ கட்டண விருப்பங்களைக் கொண்ட இந்தியாவின் மிகப்பெரிய கட்டண நுழைவாயில்.',
    'gateway_desc_payu' => '50+ சந்தைகளில் உலகளாவிய கட்டண தளம் உள்ளது, உள்ளூர் மற்றும் சர்வதேச கட்டண முறைகளை ஆதரிக்கிறது.',
    'gateway_desc_worldpay' => 'கட்டணச் செயலாக்கத்தில் உலகளாவிய முன்னணி - 146 நாடுகளில் அட்டைகள் மற்றும் மாற்றுக் கட்டண முறைகளை ஏற்கவும்.',
    'gateway_desc_klarna' => 'வாங்க-இப்போது-செலுத்த-பின்னர், தவணைத் திட்டங்கள் மற்றும் செக் அவுட்டில் மாற்றங்களை அதிகரிக்க நெகிழ்வான நிதியளிப்பு விருப்பங்களை வழங்குங்கள்.',
    'gateway_desc_afterpay' => 'வாடிக்கையாளர்கள் வாங்குவதை வட்டியில்லா 4 தவணைகளாகப் பிரித்து, சராசரி ஆர்டர் மதிப்பு மற்றும் மாற்றத்தை அதிகரிக்கும்.',
    'webhook_secret' => 'Webhook ரகசியம்',
    'webhook_purpose_subscription_charged' => 'தானாக புதுப்பித்தல் உண்மையில் வேலை செய்ய வேண்டும் - அது இல்லாமல், Razorpay வாடிக்கையாளரிடம் கட்டணம் வசூலித்த பிறகும் புதுப்பிக்கப்பட்ட சந்தாக்கள் நீட்டிக்கப்படாது.',
    'webhook_purpose_subscription_pending' => 'முதல் முயற்சியில் தோல்வியுற்ற புதுப்பித்தல் கட்டணத்தை பதிவு செய்ய வேண்டும் - அது இல்லாமல், Razorpay அதன் அனைத்து மறுமுயற்சிகளையும் தீரும் வரை போராடும் தானாகப் புதுப்பித்தல் கண்ணுக்குத் தெரியாது.',
    'webhook_purpose_subscription_halted' => 'தோல்வியுற்ற புதுப்பித்தல்களைக் கண்டறிவதற்குத் தேவை - அது இல்லாமல், ஒரு தொடர்ச்சியான கட்டணம் வேலை செய்வதை நிறுத்தியதை ஆப்ஸ் அறியாது, மேலும் தானாக புதுப்பித்தல் அமைதியாக உடைந்து விடும்.',
    'webhook_purpose_payment_captured' => 'இன்வாய்ஸ்/ஆர்டர் கொடுப்பனவுகளை உறுதிப்படுத்த வேண்டும் - இது இல்லாமல், ஒரு வாடிக்கையாளர் வெற்றிகரமாக பணம் செலுத்த முடியும் மற்றும் இன்வாய்ஸ் இன்னும் பணம் செலுத்தியதாகக் குறிக்கப்படாது.',
    'webhook_purpose_payment_failed' => 'தோல்வியுற்ற கட்டணங்களைக் கண்டறிவது அவசியம் - அது இல்லாமல், தோல்வியுற்ற பணம் செலுத்தும் முயற்சி கவனிக்கப்படாமல் போகும், மேலும் வாடிக்கையாளரை மீண்டும் முயற்சிக்குமாறு கூறப்படுவதில்லை.',
    'webhook_purpose_invoice_payment_succeeded' => 'தானாக புதுப்பித்தல் உண்மையில் வேலை செய்யத் தேவை - அது இல்லாமல், ஸ்ட்ரைப் வாடிக்கையாளரிடம் கட்டணம் வசூலித்த பிறகும் புதுப்பிக்கப்பட்ட சந்தாக்கள் நீட்டிக்கப்படாது.',
    'webhook_purpose_invoice_payment_failed' => 'தோல்வியுற்ற புதுப்பித்தல்களைக் கண்டறிவதற்குத் தேவை - இது இல்லாமல், தொடர்ச்சியான கட்டணம் வேலை செய்வதை நிறுத்தியது என்பதை ஆப்ஸ் அறியாது, மேலும் தானாகப் புதுப்பித்தல் அமைதியாக உடைந்துவிடும்.',
    'webhook_purpose_customer_subscription_deleted' => 'தானியங்கு புதுப்பித்தல் நிலையைத் துல்லியமாக வைத்திருக்க வேண்டும் - அது இல்லாமல், ஸ்ட்ரைப்பில் ரத்துசெய்யப்பட்ட சந்தா இன்னும் இங்கே செயலில் உள்ளது.',
    'webhook_purpose_checkout_session_completed' => 'உட்பொதிக்கப்பட்ட செக் அவுட் மூலம் செய்யப்பட்ட இன்வாய்ஸ்/ஆர்டர் செலுத்துதல்களை உறுதிப்படுத்த வேண்டும் - இது இல்லாமல், ஒரு வாடிக்கையாளர் வெற்றிகரமாக பணம் செலுத்த முடியும் மற்றும் இன்வாய்ஸ் இன்னும் பணம் செலுத்தியதாகக் குறிக்கப்படாது.',
    'webhook_purpose_payment_intent_succeeded' => 'கார்டு மூலம் செய்யப்பட்ட இன்வாய்ஸ்/ஆர்டர் பேமெண்ட்களை உறுதிப்படுத்த வேண்டும் - இது இல்லாமல், ஒரு வாடிக்கையாளர் வெற்றிகரமாக பணம் செலுத்த முடியும் மற்றும் இன்வாய்ஸ் இன்னும் பணம் செலுத்தியதாகக் குறிக்கப்படாது.',
    'webhook_purpose_payment_intent_payment_failed' => 'தோல்வியுற்ற கட்டணங்களைக் கண்டறிய வேண்டும் - அது இல்லாமல், தோல்வியுற்ற பணம் செலுத்தும் முயற்சி கவனிக்கப்படாமல் போகும், மேலும் வாடிக்கையாளரை மீண்டும் முயற்சிக்கச் சொல்ல முடியாது.',
