    'enter_msg91_auth_key_placeholder' => 'உங்கள் MSG91 அங்கீகார விசையை உள்ளிடவும்',
    'enter_sender_id_placeholder' => 'அனுப்புநர் ஐடியை உள்ளிடவும்',
    'enter_template_id_placeholder' => 'டெம்ப்ளேட் ஐடியை உள்ளிடவும்',
